// Minimal shadcn/ui-style primitives (hand-written, Tailwind). Not generated by the shadcn CLI.
import clsx from "clsx";
import type { ReactNode, ButtonHTMLAttributes } from "react";

export const Card = ({ title, right, children, className }: { title?: string; right?: ReactNode; children: ReactNode; className?: string }) => (
  <section className={clsx("rounded-lg border border-slate-800 bg-slate-900/70 p-4", className)}>
    {(title || right) && <header className="mb-3 flex items-center justify-between"><h2 className="text-sm font-semibold uppercase tracking-wide text-slate-400">{title}</h2>{right}</header>}
    {children}
  </section>
);

const TONES: Record<string, string> = {
  NORMAL: "bg-green-500/15 text-green-400 border-green-500/40", ONLINE: "bg-green-500/15 text-green-400 border-green-500/40",
  ABNORMAL: "bg-amber-500/15 text-amber-400 border-amber-500/40", MEDIUM: "bg-amber-500/15 text-amber-400 border-amber-500/40", DEGRADED: "bg-amber-500/15 text-amber-400 border-amber-500/40",
  PREDICTED_FAILURE: "bg-red-500/15 text-red-400 border-red-500/40", HIGH: "bg-red-500/15 text-red-400 border-red-500/40", CRITICAL: "bg-red-600/25 text-red-300 border-red-500/60",
  LOW: "bg-sky-500/15 text-sky-300 border-sky-500/40",
  OFFLINE: "bg-slate-500/20 text-slate-300 border-slate-500/40", UNKNOWN: "bg-slate-500/20 text-slate-300 border-slate-500/40", RESOLVED: "bg-slate-500/20 text-slate-300 border-slate-500/40", ACTIVE: "bg-red-500/15 text-red-400 border-red-500/40",
};
export const Badge = ({ v, children }: { v: string; children?: ReactNode }) => (
  <span className={clsx("inline-block rounded border px-2 py-0.5 text-xs font-medium", TONES[v] ?? "bg-slate-700/40 text-slate-300 border-slate-600")}>{children ?? v.replace(/_/g, " ")}</span>
);

export const Stat = ({ label, value, tone }: { label: string; value: ReactNode; tone?: string }) => (
  <div className="rounded-lg border border-slate-800 bg-slate-900/70 p-4">
    <div className="text-xs uppercase tracking-wide text-slate-400">{label}</div>
    <div className={clsx("mt-1 text-2xl font-semibold", tone)}>{value}</div>
  </div>
);

export const Button = ({ className, ...p }: ButtonHTMLAttributes<HTMLButtonElement>) => (
  <button {...p} className={clsx("rounded-md border border-slate-600 bg-slate-800 px-3 py-1.5 text-sm font-medium hover:bg-slate-700 disabled:opacity-40", className)} />
);

export const Note = ({ children }: { children: ReactNode }) => (
  <p className="rounded border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-xs text-amber-200">{children}</p>
);

export const fmt = (v: number | null | undefined, d = 1) => (v === null || v === undefined ? "–" : v.toFixed(d));
export const when = (s: string) => new Date(s.endsWith("Z") || s.includes("+") ? s : s + "Z").toLocaleString([], { month: "short", day: "2-digit", hour: "2-digit", minute: "2-digit", timeZone: "UTC" }) + " UTC";
export const STATUS_COLOR: Record<string, string> = { NORMAL: "#22c55e", ABNORMAL: "#f59e0b", PREDICTED_FAILURE: "#ef4444", OFFLINE: "#6b7280", UNKNOWN: "#6b7280" };
